<?php require '../includes/core.php';$u=require_user(true);$s=db()->query('SELECT t.*,u.name client FROM tickets t JOIN users u ON u.id=t.user_id ORDER BY t.created_at DESC');layout_start('Todos os chamados',$u);?><h1>Chamados da equipe</h1><div class="card table-wrap"><table class="table"><tr><th>Nº</th><th>Cliente</th><th>Assunto</th><th>Prioridade</th><th>Status</th><th></th></tr><?php foreach($s as $t):?><tr><td>#<?=$t['id']?></td><td><?=h($t['client'])?></td><td><?=h($t['subject'])?></td><td><?=h($t['priority'])?></td><td><?=status_badge($t['status'])?></td><td><a href="ticket.php?id=<?=$t['id']?>">Gerenciar</a></td></tr><?php endforeach;?></table></div><?php layout_end();?>